def humanize(t):

    m, s = divmod(t, 60)
    if s:
        m += 1                 # ceil minutes 
    h, m = divmod(m, 60)
    if m and h:
        h += 1                 # ceil hours
#    d, h = divmod(h, 24)

    if h > 1:
        res = 'in %d hours' % h
    elif h == 1:
        res = 'in an hour'
    else:
        if m > 1:
            res = 'in %d minutes' % m
        elif m == 1:
